package com.smartblog.service.impl;
import com.smartblog.dto.request.AccountDeleteRequest; import com.smartblog.dto.response.EmailCodeResponse; import com.smartblog.entity.*; import com.smartblog.exception.BusinessException; import com.smartblog.mapper.*; import com.smartblog.service.*; import com.smartblog.util.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AccountServiceImpl implements AccountService { private final UserIdentityMapper identityMapper; private final UserMapper userMapper; private final AuthSessionMapper sessionMapper; private final AccountDeletionRequestMapper deletionMapper; private final EmailCodeService codeService; private final SecurityEventService eventService; public AccountServiceImpl(UserIdentityMapper i,UserMapper u,AuthSessionMapper s,AccountDeletionRequestMapper d,EmailCodeService c,SecurityEventService e){identityMapper=i;userMapper=u;sessionMapper=s;deletionMapper=d;codeService=c;eventService=e;} public EmailCodeResponse sendDeleteCode(Long userId,HttpServletRequest req){UserIdentity email=identityMapper.selectByUserIdAndType(userId,AuthConstants.IDENTITY_EMAIL); if(email==null) throw new BusinessException("当前账号未绑定邮箱"); return codeService.sendCode(AuthConstants.SCENE_DELETE_ACCOUNT,email.getNormalizedValue(),req);} @Transactional public void requestDelete(Long userId,AccountDeleteRequest r,HttpServletRequest req){UserIdentity email=identityMapper.selectByUserIdAndType(userId,AuthConstants.IDENTITY_EMAIL); if(email==null) throw new BusinessException("当前账号未绑定邮箱"); codeService.verifyCode(AuthConstants.SCENE_DELETE_ACCOUNT,email.getNormalizedValue(),r.emailCode()); AccountDeletionRequest adr=new AccountDeletionRequest(); adr.setUserId(userId); adr.setStatus(1); adr.setReason(r.reason()); deletionMapper.insert(adr); userMapper.updateStatus(userId,AuthConstants.USER_PENDING_DELETION); sessionMapper.revokeAllByUserId(userId); eventService.log(userId,AuthConstants.EVENT_DELETE_REQUEST,AuthConstants.RESULT_SUCCESS,req,"pending-delete");} }
